import numpy as np
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
names=[];cols=[]
for tn,tv in [('1',np.ones(300)),('t',t),('t2',t**2)]:
    for pn,pv in [('1',np.ones(300)),('P',P),('P2',P**2),('P3',P**3),('PlnP',P*np.log(P))]:
        names.append(tn+'*'+pn); cols.append(tv*pv)
X=np.array(cols).T
c=np.linalg.lstsq(X,y,rcond=None)[0]
for n,v in zip(names,c): print(n, round(v,5))
